// 由 tools/bottles/bottles.py 生成，勿手改。全部为公有领域真实史料摘录，来源见 docs/bottle-history-sources.md

extension VoyageConfig {
    public static let historyBottles: [HistoryBottle] = [
        .init(id: 100, oceanID: "coastal", kind: .diary, date: "742", en: "The Venerable said: “This is for the sake of the Dharma — why begrudge one's life? If no one else will go, I shall go.”", zh: "大和上说：“为了弘法，何必吝惜性命？大家不去，我就去。”", original: "大和上曰︰「爲是法事也，何惜身命？諸人不去，我卽去耳。」", noteZh: "742 年，日本僧人荣叡、普照到扬州请鉴真东渡传戒，鉴真当众说出这句话。此后他六次出海，前五次都失败了。", noteEn: "In 742 Japanese monks asked Jianzhen to carry Buddhist precepts to Japan; he answered with these words, and went on to attempt the crossing six times.", sourceZh: "真人元开《唐大和上东征传》（779）", sourceEn: "Ōmi no Mifune, Tō Daiwajō Tōseiden (779)", url: "https://zh.wikisource.org/wiki/唐大和上東征傳"),
        .init(id: 101, oceanID: "coastal", kind: .diary, date: "748", en: "There was no water on board. We chewed raw rice, but our throats were too dry to swallow it, and we could not spit it out; when we drank sea water, our bellies swelled.", zh: "船上没有淡水。嚼生米，喉咙干得咽不下，也吐不出来；喝了海水，肚子就胀起来。", original: "舟上無水，嚼米，喉乾咽不入，吐不出；飲鹹水，腹卽脹。", noteZh: "第五次东渡（748）遇台风，船漂流十多天，最后漂到海南岛。", noteEn: "On the fifth attempt (748) a typhoon drove the ship south for days; it finally came ashore on Hainan.", sourceZh: "真人元开《唐大和上东征传》（779）", sourceEn: "Ōmi no Mifune, Tō Daiwajō Tōseiden (779)", url: "https://zh.wikisource.org/wiki/唐大和上東征傳"),
        .init(id: 102, oceanID: "coastal", kind: .diary, date: "748", en: "For three days we passed through the Sea of Flying Fish. White flying fish filled the sky, each about a foot long.", zh: "三天里经过“飞鱼海”。白色的飞鱼遮满天空，每条一尺来长。", original: "三日過飛魚海。白色飛魚，翳滿空中，長一尺許。", noteZh: "同一次漂流中的见闻。鉴真后来双目失明，753 年第六次东渡终于抵达日本。", noteEn: "From the same drift. Jianzhen later lost his sight, and finally reached Japan on his sixth attempt in 753.", sourceZh: "真人元开《唐大和上东征传》（779）", sourceEn: "Ōmi no Mifune, Tō Daiwajō Tōseiden (779)", url: "https://zh.wikisource.org/wiki/唐大和上東征傳"),
        .init(id: 103, oceanID: "coastal", kind: .log, date: "1431", en: "Since the third year of Yongle we have been sent to the Western Ocean seven times… more than thirty countries great and small, crossing over a hundred thousand li of open sea.", zh: "从永乐三年起，奉命出使西洋，至今已经七次……大大小小三十多个国家，渡过十多万里沧海。", original: "自永樂三年，奉使西洋，迨今七次……大小凡三十餘國，涉滄溟十萬餘里。", noteZh: "1431 年郑和第七次下西洋前，在福建长乐立碑记述历次航程。", noteEn: "Erected at Changle, Fujian, in 1431 before Zheng He's seventh voyage, recording the earlier ones.", sourceZh: "郑和等《天妃之神灵应记》碑（长乐，1431）", sourceEn: "Zheng He et al., Changle Tianfei stele (1431)", url: "https://zh.wikisource.org/wiki/天妃之神靈應記"),
        .init(id: 104, oceanID: "coastal", kind: .log, date: "1431", en: "The waves rise like mountains… yet with our cloud-sails set high we race day and night like shooting stars, crossing the wild billows as if walking a broad road.", zh: "巨浪像山一样……而我们高张云帆，日夜如流星般疾驰，越过狂澜，就像走在大路上。", original: "洪濤接天，巨浪如山……而我之雲帆高張，晝夜星馳，涉彼狂瀾，若履通衢者。", noteZh: "同一块碑。郑和船队在 1405–1433 年间七下西洋，最远到东非。", noteEn: "From the same stele. Zheng He's fleets sailed seven times between 1405 and 1433, reaching East Africa.", sourceZh: "郑和等《天妃之神灵应记》碑（长乐，1431）", sourceEn: "Zheng He et al., Changle Tianfei stele (1431)", url: "https://zh.wikisource.org/wiki/天妃之神靈應記"),
        .init(id: 110, oceanID: "atlantic", kind: .diary, date: "1620", en: "In a mighty storm, a lusty young man (called John Howland)… was thrown into the sea; but it pleased God that he caught hold of the top-sail halyards… and his life saved.", zh: "在一场猛烈的风暴里，一个强壮的年轻人（名叫约翰·豪兰）……被甩进海里；但上帝保佑，他抓住了顶帆的升降索……保住了性命。", original: "", noteZh: "1620 年五月花号横渡大西洋途中的真事。豪兰后来活到八十岁，后代很多。", noteEn: "A true episode of the Mayflower crossing in 1620; Howland lived to his eighties.", sourceZh: "William Bradford《普利茅斯开拓史》（1630–51 写成，1898 版）", sourceEn: "William Bradford, Of Plimoth Plantation (1898 ed.)", url: "https://www.gutenberg.org/ebooks/24950"),
        .init(id: 111, oceanID: "atlantic", kind: .diary, date: "1620", en: "Being thus arrived in a good harbor and brought safe to land, they fell upon their knees & blessed the God of heaven, who had brought them over the vast & furious ocean.", zh: "就这样到达了良港、平安上岸，他们跪下来感谢天上的神，带他们渡过了浩瀚而狂暴的大洋。", original: "", noteZh: "1620 年 11 月五月花号抵达科德角。原文为 17 世纪拼写，此处改为现代拼写。", noteEn: "The Mayflower reached Cape Cod in November 1620. Spelling modernised from the 17th-century original.", sourceZh: "William Bradford《普利茅斯开拓史》（1630–51 写成，1898 版）", sourceEn: "William Bradford, Of Plimoth Plantation (1898 ed.)", url: "https://www.gutenberg.org/ebooks/24950"),
        .init(id: 112, oceanID: "atlantic", kind: .letter, date: "1803", en: "You cannot, I am sure, more ardently long to see me, than I do to be with you.", zh: "我相信，你想见我的心，不会比我想和你在一起的心更迫切。", original: "", noteZh: "纳尔逊在地中海舰队旗舰上写给艾玛·汉密尔顿的情书。1805 年他在特拉法加海战中阵亡。", noteEn: "A love letter from Nelson at sea to Emma Hamilton. He was killed at Trafalgar in 1805.", sourceZh: "《纳尔逊致汉密尔顿夫人书信集》第一卷（1814）", sourceEn: "The Letters of Lord Nelson to Lady Hamilton, Vol. I (1814)", url: "https://www.gutenberg.org/ebooks/15469"),
        .init(id: 113, oceanID: "atlantic", kind: .telegram, date: "1912", en: "“Come at once; this is a distress message. C. Q. D.”", zh: "“速来；这是遇险信号。C. Q. D.”", original: "", noteZh: "1912 年 4 月 14 日深夜，泰坦尼克号报务员这样回复卡帕西亚号的报务员 Cottam（据他在美国参议院听证会上的证词）。卡帕西亚号救起了约 700 名幸存者，有 1,500 多人罹难。", noteEn: "Titanic's reply to Carpathia's operator Harold Cottam, per his US Senate testimony. Carpathia rescued about 700 people; more than 1,500 died.", sourceZh: "Logan Marshall 编《泰坦尼克号沉没》（1912）", sourceEn: "Logan Marshall (ed.), Sinking of the Titanic and Great Sea Disasters (1912)", url: "https://www.gutenberg.org/ebooks/781"),
        .init(id: 114, oceanID: "atlantic", kind: .telegram, date: "1912", en: "“All Titanic's passengers safe.” …in reality the message should have read: “Are all Titanic's passengers safe?”", zh: "“泰坦尼克号全体乘客平安。”……其实这条电报原本应该是：“泰坦尼克号全体乘客平安吗？”", original: "", noteZh: "混乱的无线电通信里，一个问句被误收成了好消息，岸上的家人因此空欢喜了一夜。", noteEn: "In the chaos of wireless traffic a question was received as good news, and families ashore were falsely reassured for a night.", sourceZh: "Logan Marshall 编《泰坦尼克号沉没》（1912）", sourceEn: "Logan Marshall (ed.), Sinking of the Titanic and Great Sea Disasters (1912)", url: "https://www.gutenberg.org/ebooks/781"),
        .init(id: 120, oceanID: "pacific", kind: .diary, date: "1520", en: "We only ate old biscuit reduced to powder, and full of grubs… We also ate the ox hides which were under the main-yard.", zh: "我们只能吃已经碎成粉、满是蛆虫的陈饼干……还吃了主帆桁下面的牛皮。", original: "", noteZh: "麦哲伦船队 1520 年 11 月出海峡进入太平洋，三个多月没有补给，坏血病夺走了许多人的生命。", noteEn: "After leaving the strait in November 1520, Magellan's fleet crossed the Pacific for over three months without fresh food; many died of scurvy.", sourceZh: "Pigafetta《麦哲伦环球首航》，Stanley 英译（1874）", sourceEn: "Antonio Pigafetta, The First Voyage Round the World by Magellan, tr. Lord Stanley (1874)", url: "https://www.gutenberg.org/ebooks/74723"),
        .init(id: 121, oceanID: "pacific", kind: .diary, date: "1521", en: "This was well named Pacific, for during this same time we met with no storm.", zh: "这片海叫“太平洋”真是名副其实，因为这段时间里我们一场风暴也没遇到。", original: "", noteZh: "“太平洋”之名就来自这次航行。麦哲伦本人 1521 年死于菲律宾，维多利亚号 1522 年回到西班牙，完成首次环球航行。", noteEn: "The name 'Pacific' comes from this voyage. Magellan died in the Philippines in 1521; the Victoria completed the first circumnavigation in 1522.", sourceZh: "Pigafetta《麦哲伦环球首航》，Stanley 英译（1874）", sourceEn: "Antonio Pigafetta, The First Voyage Round the World by Magellan, tr. Lord Stanley (1874)", url: "https://www.gutenberg.org/ebooks/74723"),
        .init(id: 122, oceanID: "pacific", kind: .journal, date: "1820", en: "A whale had come up directly under her, and with one dash of his tail, had stove her bottom in… Strange to tell, not a man was injured.", zh: "一头鲸正好从小艇底下冒上来，尾巴一甩就把艇底打穿了……说来也怪，竟没有一个人受伤。", original: "", noteZh: "捕鲸船埃塞克斯号大副 Owen Chase 的记述（1820 年 11 月）。几天后，一头抹香鲸撞沉了大船本身。", noteEn: "Whaleship Essex first mate Owen Chase, November 1820. Days later a sperm whale sank the ship itself.", sourceZh: "Owen Chase《埃塞克斯号捕鲸船海难纪实》（1821）", sourceEn: "Owen Chase, Narrative of the … Shipwreck of the Whale-ship Essex (1821)", url: "https://www.gutenberg.org/ebooks/61931"),
        .init(id: 123, oceanID: "pacific", kind: .journal, date: "1820", en: "I perceived the head of the ship to be gradually settling down in the water.", zh: "我发现船头正一点点沉进水里。", original: "", noteZh: "埃塞克斯号沉没后，船员在小艇里漂流了三个月，20 人中只有 8 人生还。这件事启发了《白鲸》。", noteEn: "After the sinking the crew drifted for three months in open boats; only 8 of 20 survived. The story inspired Moby-Dick.", sourceZh: "Owen Chase《埃塞克斯号捕鲸船海难纪实》（1821）", sourceEn: "Owen Chase, Narrative of the … Shipwreck of the Whale-ship Essex (1821)", url: "https://www.gutenberg.org/ebooks/61931"),
        .init(id: 124, oceanID: "pacific", kind: .log, date: "1770", en: "Before the Man at the Lead could heave another cast, the Ship Struck and stuck fast… we had got upon the South-East Edge of a reef of Coral Rocks.", zh: "测深的水手还来不及再投一次铅锤，船就撞上并搁住了……我们撞上了一片珊瑚礁的东南边缘。", original: "", noteZh: "1770 年 6 月，库克的奋进号在今澳大利亚大堡礁触礁，船员抛掉大炮等重物才脱险。", noteEn: "June 1770: Cook's Endeavour struck what is now the Great Barrier Reef; the crew threw guns overboard to float her off.", sourceZh: "《库克船长第一次环球航行日志》，Wharton 编（1893）", sourceEn: "Captain Cook's Journal During His First Voyage Round the World, ed. Wharton (1893)", url: "https://www.gutenberg.org/ebooks/8106"),
        .init(id: 125, oceanID: "pacific", kind: .log, date: "1789", en: "At night I served a quarter of a bread-fruit and a cocoa-nut to each person for supper.", zh: "晚上，我给每人分了四分之一个面包果和一个椰子当晚饭。", original: "", noteZh: "邦蒂号叛变后，布莱和 18 名船员被赶上一条小艇，靠严格配给航行约 3,600 海里到达帝汶。", noteEn: "After the Bounty mutiny, Bligh and 18 men sailed some 3,600 nautical miles to Timor in an open launch on strict rations.", sourceZh: "William Bligh《邦蒂号叛变记》（1790）", sourceEn: "William Bligh, A Narrative of the Mutiny on board HMS Bounty (1790)", url: "https://www.gutenberg.org/ebooks/20337"),
        .init(id: 130, oceanID: "indian", kind: .log, date: "1498", en: "The first greeting that he received was in these words: “May the Devil take thee! What brought you hither?” …he told them that we came in search of Christians and of spices.", zh: "他听到的第一句问候是：“见鬼！你们来这儿干什么？”……他回答说，我们来寻找基督徒和香料。", original: "", noteZh: "1498 年 5 月达·伽马船队抵达印度卡利卡特，打通了欧洲绕过非洲到印度的航路。", noteEn: "Vasco da Gama's fleet reached Calicut in May 1498, opening the sea route from Europe round Africa to India.", sourceZh: "《达·伽马首航日志 1497–1499》，Ravenstein 英译（1898）", sourceEn: "A Journal of the First Voyage of Vasco da Gama, tr. Ravenstein (1898)", url: "https://www.gutenberg.org/ebooks/46440"),
        .init(id: 131, oceanID: "indian", kind: .log, date: "1498", en: "“A lucky venture, a lucky venture! Plenty of rubies, plenty of emeralds!” …we never expected to hear our language spoken so far away from Portugal.", zh: "“好运气，好运气！多的是红宝石，多的是绿宝石！”……我们从没想过，离葡萄牙这么远还能听到自己的语言。", original: "", noteZh: "说这话的是一位会讲西班牙语的突尼斯商人。日志作者一般认为是船员 Álvaro Velho。", noteEn: "Spoken by a Tunisian merchant who knew Castilian. The journal is usually attributed to crewman Álvaro Velho.", sourceZh: "《达·伽马首航日志 1497–1499》，Ravenstein 英译（1898）", sourceEn: "A Journal of the First Voyage of Vasco da Gama, tr. Ravenstein (1898)", url: "https://www.gutenberg.org/ebooks/46440"),
        .init(id: 132, oceanID: "indian", kind: .diary, date: "1836", en: "Farewell, Australia! you are a rising child, and doubtless some day will reign a great princess in the South.", zh: "再见了，澳大利亚！你是个正在成长的孩子，总有一天会成为南方的一位伟大公主。", original: "", noteZh: "1836 年 3 月，小猎犬号离开澳大利亚，横渡印度洋前往基林群岛。", noteEn: "March 1836: the Beagle left Australia to cross the Indian Ocean to the Keeling Islands.", sourceZh: "达尔文《小猎犬号航海记》（1839/1845）", sourceEn: "Charles Darwin, The Voyage of the Beagle (1839/1845)", url: "https://www.gutenberg.org/ebooks/944"),
        .init(id: 133, oceanID: "indian", kind: .diary, date: "1836", en: "As a white cloud here and there affords a pleasing contrast with the azure sky, so in the lagoon, bands of living coral darken the emerald green water.", zh: "就像蓝天里点缀着几朵白云，潟湖里一条条活珊瑚，让翡翠般的海水颜色更深。", original: "", noteZh: "达尔文在基林（科科斯）环礁观察珊瑚，后来提出了环礁形成理论。", noteEn: "At Keeling (Cocos) atoll Darwin studied the coral that led to his theory of how atolls form.", sourceZh: "达尔文《小猎犬号航海记》（1839/1845）", sourceEn: "Charles Darwin, The Voyage of the Beagle (1839/1845)", url: "https://www.gutenberg.org/ebooks/944"),
        .init(id: 140, oceanID: "arctic", kind: .diary, date: "1893", en: "In the north are quivering arches of faint aurora… never at peace, restless as the very soul of man.", zh: "北边是颤动着的淡淡极光弧……从不平静，像人的灵魂一样不安。", original: "", noteZh: "南森故意让前进号冻在浮冰里随冰漂流，想漂过北极。这是漫长极夜里的一个星期天。", noteEn: "Nansen let the Fram freeze into the pack to drift across the Arctic. A Sunday in the long polar night.", sourceZh: "南森《最远的北方》第一卷（1897）", sourceEn: "Fridtjof Nansen, Farthest North, Vol. I (1897)", url: "https://www.gutenberg.org/ebooks/30197"),
        .init(id: 141, oceanID: "arctic", kind: .diary, date: "1895", en: "On this northernmost camping-ground we indulged in a banquet, consisting of lobscouse, bread-and-butter, dry chocolate, stewed … red whortleberries.", zh: "在这个最北的营地，我们大吃了一顿：炖杂烩、黄油面包、干巧克力，还有炖……红越橘。", original: "", noteZh: "1895 年春，南森和约翰森离开前进号，乘雪橇向北极点冲刺。", noteEn: "Spring 1895: Nansen and Johansen left the Fram to push for the Pole by sledge.", sourceZh: "南森《最远的北方》第二卷（1897）", sourceEn: "Fridtjof Nansen, Farthest North, Vol. II (1897)", url: "https://www.gutenberg.org/ebooks/34120"),
        .init(id: 142, oceanID: "arctic", kind: .log, date: "1895", en: "On April 6, 1895, we had to turn back at 86° 14' north latitude… the ice having become impassable.", zh: "1895 年 4 月 6 日，我们在北纬 86°14′ 不得不折返……冰已经无法通过。", original: "", noteZh: "这是当时人类到达过的最北纬度。", noteEn: "At the time, the farthest north anyone had reached.", sourceZh: "南森《最远的北方》第二卷（1897）", sourceEn: "Fridtjof Nansen, Farthest North, Vol. II (1897)", url: "https://www.gutenberg.org/ebooks/34120"),
        .init(id: 143, oceanID: "arctic", kind: .diary, date: "1896", en: "“Aren't you Nansen?” “Yes, I am.” “By Jove! I am glad to see you!”", zh: "“你不是南森吗？”“是的，我是。”“天哪！见到你真高兴！”", original: "", noteZh: "在冰上熬过一个冬天后，1896 年 6 月南森在法兰士约瑟夫地偶遇英国探险家杰克逊，得救回家。", noteEn: "After wintering on the ice, Nansen met the British explorer Jackson at Franz Josef Land in June 1896 and was brought home.", sourceZh: "南森《最远的北方》第二卷（1897）", sourceEn: "Fridtjof Nansen, Farthest North, Vol. II (1897)", url: "https://www.gutenberg.org/ebooks/34120"),
        .init(id: 150, oceanID: "southern", kind: .diary, date: "1915", en: "To a sailor his ship is more than a floating home… She is crushed and abandoned after drifting more than 570 miles.", zh: "对水手来说，船不只是一个漂浮的家……她被压碎、被弃，此前已随冰漂流了 570 多英里。", original: "", noteZh: "1915 年，坚忍号被威德尔海浮冰挤碎。沙克尔顿最终带全部 28 人生还。", noteEn: "In 1915 the Endurance was crushed by Weddell Sea ice. Shackleton eventually brought all 28 men home.", sourceZh: "沙克尔顿《南方》（1919）", sourceEn: "Ernest Shackleton, South (1919)", url: "https://www.gutenberg.org/ebooks/5199"),
        .init(id: 151, oceanID: "southern", kind: .diary, date: "1916", en: "We had seen God in His splendours, heard the text that Nature renders. We had reached the naked soul of man.", zh: "我们见过上帝的辉煌，听过大自然的经文。我们触到了人最赤裸的灵魂。", original: "", noteZh: "1916 年 5 月，沙克尔顿等三人徒步翻越南乔治亚岛的冰山，到达捕鲸站求救。", noteEn: "May 1916: Shackleton and two companions crossed the mountains of South Georgia on foot to reach a whaling station.", sourceZh: "沙克尔顿《南方》（1919）", sourceEn: "Ernest Shackleton, South (1919)", url: "https://www.gutenberg.org/ebooks/5199"),
        .init(id: 152, oceanID: "southern", kind: .diary, date: "1912", en: "He said, 'I am just going outside and may be some time.' He went out into the blizzard and we have not seen him since.", zh: "他说：“我出去一下，可能要一阵子。”他走进暴风雪，我们再也没有见到他。", original: "", noteZh: "斯科特记下奥茨上尉的最后一句话。奥茨冻伤严重，为了不拖累同伴独自走出帐篷。", noteEn: "Scott records Captain Oates's last words. Badly frostbitten, Oates walked out so as not to hold the others back.", sourceZh: "《斯科特最后的探险》第一卷（1913）", sourceEn: "Scott's Last Expedition, Vol. I (1913)", url: "https://www.gutenberg.org/ebooks/11579"),
        .init(id: 153, oceanID: "southern", kind: .diary, date: "1912", en: "It seems a pity, but I do not think I can write more. R. SCOTT. For God's sake look after our people.", zh: "很遗憾，但我想我写不下去了。R. 斯科特。看在上帝分上，请照顾我们的家人。", original: "", noteZh: "斯科特日记的最后一条（1912 年 3 月）。返程中五人全部遇难，八个月后搜救队找到帐篷。", noteEn: "The last entry in Scott's journal, March 1912. All five of the polar party died; a search party found the tent eight months later.", sourceZh: "《斯科特最后的探险》第一卷（1913）", sourceEn: "Scott's Last Expedition, Vol. I (1913)", url: "https://www.gutenberg.org/ebooks/11579"),
        .init(id: 154, oceanID: "southern", kind: .letter, date: "1912", en: "Had we lived, I should have had a tale to tell of the hardihood, endurance, and courage of my companions.", zh: "如果我们能活下来，我本可以讲一个关于同伴们坚韧、忍耐和勇气的故事。", original: "", noteZh: "出自斯科特的《致公众书》，写于生命最后几天。", noteEn: "From Scott's 'Message to the Public', written in his final days.", sourceZh: "《斯科特最后的探险》第一卷（1913）", sourceEn: "Scott's Last Expedition, Vol. I (1913)", url: "https://www.gutenberg.org/ebooks/11579"),
        .init(id: 155, oceanID: "southern", kind: .diary, date: "1911", en: "Polar exploration is at once the cleanest and most isolated way of having a bad time which has been devised.", zh: "极地探险，是人类想出来的最干净、也最孤独的受罪方式。", original: "", noteZh: "Cherry-Garrard 参加了斯科特探险队，1911 年隆冬曾为采集帝企鹅蛋走过“世界最险恶之旅”。", noteEn: "Cherry-Garrard sailed with Scott; in midwinter 1911 he made the 'worst journey in the world' to collect emperor penguin eggs.", sourceZh: "Cherry-Garrard《世界最险恶之旅》（1922）", sourceEn: "Apsley Cherry-Garrard, The Worst Journey in the World (1922)", url: "https://www.gutenberg.org/ebooks/14363"),
        .init(id: 156, oceanID: "southern", kind: .diary, date: "1911", en: "“Good God! here is the Crozier Party,” said a voice, and disappeared. Thus ended the worst journey in the world.", zh: "“天哪！克罗泽小队回来了！”一个声音说完就不见了。世界最险恶之旅就这样结束了。", original: "", noteZh: "三人在零下 60 度的极夜里拖雪橇五周，带回了三枚帝企鹅蛋。", noteEn: "The three men hauled sledges for five weeks in the polar night at around −60°, returning with three emperor penguin eggs.", sourceZh: "Cherry-Garrard《世界最险恶之旅》（1922）", sourceEn: "Apsley Cherry-Garrard, The Worst Journey in the World (1922)", url: "https://www.gutenberg.org/ebooks/14363"),
        .init(id: 157, oceanID: "southern", kind: .diary, date: "1836", en: "No description can give any idea of the strangeness, splendor, and, really, the sublimity, of the sight.", zh: "任何描述都无法表达那景象的奇异、壮丽，乃至崇高。", original: "", noteZh: "达纳当水手绕合恩角回航时，在南方冰海遇到一座巨大的冰山。", noteEn: "Sailing home round Cape Horn as a common seaman, Dana met a giant iceberg in the southern ice.", sourceZh: "Richard Henry Dana《两年水手生涯》（1840）", sourceEn: "Richard Henry Dana Jr., Two Years Before the Mast (1840)", url: "https://www.gutenberg.org/ebooks/2055"),
    ]
}
